begin transaction isolation level repeatable read read only;
select jsonb_build_object(
 'captured_at',transaction_timestamp(),
 'table_rights',(select jsonb_agg(jsonb_build_object('table',c.relname,'role',r.rolname,'privilege',p.v,'allowed',has_table_privilege(r.oid,c.oid,p.v),'grant_option',has_table_privilege(r.oid,c.oid,p.v||' WITH GRANT OPTION')) order by c.relname,r.rolname,p.v) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join pg_roles r cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN'))p(v) where n.nspname='public' and c.relkind in('r','p') and r.rolname in('anon','authenticated')),
 'schema_rights',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'role',r.rolname,'usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE')) order by n.nspname,r.rolname) from pg_namespace n cross join pg_roles r where n.nspname in('public','auth','extensions','graphql_public','storage','realtime','vault') and r.rolname in('anon','authenticated')),
 'function_rights',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'role',r.rolname,'execute',has_function_privilege(r.oid,p.oid,'EXECUTE'),'grant_option',has_function_privilege(r.oid,p.oid,'EXECUTE WITH GRANT OPTION')) order by p.proname,r.rolname) from pg_proc p cross join pg_roles r where p.pronamespace='public'::regnamespace and r.rolname in('anon','authenticated')),
 'safe_role_settings',(select coalesce(jsonb_agg(jsonb_build_object('database',s.setdatabase,'role',s.setrole,'setting',v.value) order by s.setdatabase,s.setrole,v.value),'[]') from pg_db_role_setting s cross join lateral unnest(s.setconfig) v(value) where v.value ~ '^(pgrst.db_schemas|pgrst.db_extra_search_path|pgrst.db_anon_role|pgrst.db_channel|statement_timeout|idle_in_transaction_session_timeout|search_path)='),
 'reported_api_schemas',current_setting('pgrst.db_schemas',true),
 'public_counts',jsonb_build_object('tables',(select count(*) from pg_tables where schemaname='public'),'columns',(select count(*) from information_schema.columns where table_schema='public'),'policies',(select count(*) from pg_policies where schemaname='public'))
) as metadata_only; commit;
